 * dedicated {@code NOTIFY} logger, keeping notification side-effects separate from request
 * handling and persistence logic.
 */
@Component
public class WelcomeNotifier {

    private static final Logger NOTIFY = LoggerFactory.getLogger("NOTIFY");

    /**
     * Enqueue a welcome notification for the newly persisted owner, carrying its id and member id.
